output_text:
[
  {
    "id": "pickup_entry_cart",
    "text": "A shopper is obliged to pick up the entry cart from the cart bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)"
      },
      "events": {
        "pickup_entry_cart_event": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart_event"
    }
  },
  {
    "id": "do_not_pass_cart_bay_without_cart",
    "text": "A shopper should not walk away from the entry cart bay while the cart is still there and has not been taken.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "cart_still_at_entry_bay": "cartAt(1,5)"
      },
      "events": {
        "leave_entry_bay_without_cart": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "cart_still_at_entry_bay",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "not": "at(1,5)"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_entry_bay_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_items",
    "text": "Items must not be carried by hand and must not be picked up unless the shopper is pushing the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        },
        "carrying_by_hand": "handFull"
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "pickup_item_without_cart"
        ]
      }
    }
  },
  {
    "id": "pickup_only_at_product_spots",
    "text": "Product pickup interactions are only permitted at recognized shelf-facing product pickup cells.",
    "abstraction": {
      "state_properties": {
        "product_pickup_cell": {
          "or": [
            "at(1,3)",
            "at(2,2)",
            "at(3,2)",
            "at(5,2)",
            "at(6,2)",
            "at(2,4)",
            "at(3,4)",
            "at(5,4)",
            "at(6,4)"
          ]
        }
      },
      "events": {
        "product_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "product_pickup",
          {
            "not": "product_pickup_cell"
          }
        ]
      }
    }
  },
  {
    "id": "return_cart_after_use",
    "text": "After taking the entry cart, the shopper is obliged to return and park it at the cart return bay before exiting.",
    "abstraction": {
      "state_properties": {
        "entry_cart_bay": "at(1,5)",
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "pickup_entry_cart_event": {
          "pre": {
            "and": [
              "entry_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay_event": {
          "pre": {
            "and": [
              "cart_return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_entry_cart_event",
      "discharge": "return_cart_to_bay_event"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "Putting the cart down is prohibited anywhere except the designated cart return bay.",
    "abstraction": {
      "state_properties": {
        "cart_return_bay": "at(0,1)"
      },
      "events": {
        "leave_cart_event": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart_event",
          {
            "not": "cart_return_bay"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_checkout_lane",
    "text": "The bottom checkout corridor and exit may be used only on foot, not while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "bottom_checkout_corridor": {
          "or": [
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_bottom_checkout_corridor": {
          "and": [
            "hasCart",
            "bottom_checkout_corridor"
          ]
        }
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "hasCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_in_bottom_checkout_corridor",
          "exit_with_cart"
        ]
      }
    }
  },
  {
    "id": "no_interactions_after_cart_return",
    "text": "Once the cart has been parked in the return bay, the shopper should not perform any further store interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "post_return_without_cart": {
          "and": [
            "cartAt(0,1)",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "post_return_without_cart",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
